  Future<(AgentCli, FakeCliIO, _RoutingStream, _DrainShell, Future<int>)>
  gh1440Shape() async {
    final io = FakeCliIO();
    final shell = _DrainShell();
    final stream = _RoutingStream(
      leadTurns: [
