  final parts = <String>[
    if (snap.jobs.isNotEmpty)
      '${snap.jobs.length} background job'
          '${snap.jobs.length == 1 ? '' : 's'} (${snap.jobs.first})',
    if (snap.timers.isNotEmpty)
